+      faqs: result.faqs?.length ? result.faqs : FALLBACK_CONTENT.faqs
+    };
+  } catch (error) {
+    if (process.env.NODE_ENV !== "production") {
+      console.error("Failed to load bias-free policing content:", error);
+    }
+    return FALLBACK_CONTENT;
+  }
+};
